  {id:51,ko:"밀레 수락산점",en:"Suraksan명동찌개마을 2호",jp:"수락산명동찌개마을 2호점",cn:"수락산명동찌개마을 2호점",addr:"서울 노원구 동일로242길 63 1층",cat:"food",onuri:true,lat:37.674723,lng:127.058749,dist:118,hours:"11:00~22:00",dko:"수락디자인거리의 맛집. 신선한 재료와 정성으로 만든 요리를 즐길 수 있습니다. 등산 전후 방문하기 좋은 곳입니다.",den:"A beloved restaurant on Surak Design Street. Fresh ingredients and heartfelt cooking. Great before or after hiking.",djp:"スラクデザイン通りの名店。新鮮な食材と心を込めた料理。登山前後の訪問に最適。",dcn:"水落设计街的美食名店。新鲜食材精心烹制。登山前后造访的好去处。",menus:[{ko:"부대찌개(1인)",en:"Budae Jjigae(1p)",jp:"部隊チゲ(1人)",cn:"部队锅(1人)",p:"9,000원"},{ko:"부대찌개(2인)",en:"Budae Jjigae(2p)",jp:"部隊チゲ(2人)",cn:"部队锅(2人)",p:"18,000원"},{ko:"김치찌개",en:"Kimchi Jjigae",jp:"キムチチゲ",cn:"泡菜锅",p:"8,000원"},{ko:"된장찌개",en:"Doenjang Jjigae",jp:"テンジャンチゲ",cn:"大酱汤",p:"8,000원"},{ko:"라면사리",en:"Ramen Add-on",jp:"ラーメン追加",cn:"加拉面",p:"1,000원"},{ko:"치즈추가",en:"Cheese Add-on",jp:"チーズ追加",cn:"加芝士",p:"2,000원"},{ko:"공기밥",en:"Steamed Rice",jp:"ご飯",cn:"米饭",p:"1,000원"},{ko:"소주",en:"Soju",jp:"焼酎",cn:"烧酒",p:"4,000원"},{ko:"맥주",en:"Beer",jp:"ビール",cn:"啤酒",p:"4,500원"},{ko:"계란추가",en:"Egg Add-on",jp:"卵追加",cn:"加鸡蛋",p:"1,000원"},{ko:"순두부찌개",en:"Soft Tofu Stew",jp:"スンドゥブチゲ",cn:"嫩豆腐锅",p:"9,000원"}]}
